/**
 * Test: engine-less G2P C API against the Python golden fixture.
 *
 * Compares piper_plus_g2p_phonemize with
 * tests/fixtures/g2p/phoneme_test_cases_golden.json (generated by Python)
 * and reads tests/fixtures/g2p/known_divergences.json for the cases known to
 * differ (runtime "cpp", shared with the Android L3 test that wraps the same
 * library). A difference that is not listed fails, and so does a listed case
 * that now matches, so the list shrinks as the linked issues are fixed.
 *
 * One representation difference is not a divergence: libpiper_plus encodes
 * multi-codepoint phonemes (rr, tʃ, tone3) as one PUA character (pua.json);
 * the golden spells them out. Only the golden side is mapped, so output that
 * forgets the PUA encoding still fails. Chinese punctuation and word
 * boundaries are compared as they are: since Issue #823 Python keeps CJK
 * punctuation too (docs/spec/cjk-punctuation-contract.toml).
 *
 * Also checks that English words phonemize to at least one phoneme
 * (tests/fixtures/g2p/english_no_drop_words.json), with the same listing rule.
 *
 * Japanese is skipped (OpenJTalk dictionary not staged), and so is Korean,
 * which the golden omits and the trained models do not cover.
 */

#include <gtest/gtest.h>
#include "piper_plus.h"
#include "../json.hpp"

#include <cstdlib>
#include <fstream>
#include <map>
#include <set>
#include <sstream>
#include <string>
#include <utility>
#include <vector>

#ifndef PIPER_PLUS_SOURCE_DIR
#error "PIPER_PLUS_SOURCE_DIR must point at the repository root"
#endif

namespace {

using nlohmann::json;
using Key = std::pair<std::string, std::string>;  // (language, input)

const std::string kRoot = PIPER_PLUS_SOURCE_DIR;
const char *kRuntime = "cpp";

json loadJson(const std::string &relative) {
    std::ifstream in(kRoot + "/" + relative, std::ios::binary);
    if (!in) throw std::runtime_error("cannot open " + relative);
    std::stringstream buf;
    buf << in.rdbuf();
    return json::parse(buf.str());
}

std::string codepointToUtf8(unsigned cp) {
    std::string out;
    if (cp < 0x80) {
        out += static_cast<char>(cp);
    } else if (cp < 0x800) {
        out += static_cast<char>(0xC0 | (cp >> 6));
        out += static_cast<char>(0x80 | (cp & 0x3F));
    } else if (cp < 0x10000) {
        out += static_cast<char>(0xE0 | (cp >> 12));
        out += static_cast<char>(0x80 | ((cp >> 6) & 0x3F));
        out += static_cast<char>(0x80 | (cp & 0x3F));
    } else {
        out += static_cast<char>(0xF0 | (cp >> 18));
        out += static_cast<char>(0x80 | ((cp >> 12) & 0x3F));
        out += static_cast<char>(0x80 | ((cp >> 6) & 0x3F));
        out += static_cast<char>(0x80 | (cp & 0x3F));
    }
    return out;
}

std::map<std::string, std::string> loadPuaTable() {
    std::map<std::string, std::string> table;
    // Keep the document alive: ranging over a member of a temporary dangles.
    const json doc = loadJson("src/python/g2p/piper_plus_g2p/data/pua.json");
    for (const auto &e : doc["entries"]) {
        table[e["token"].get<std::string>()] =
            codepointToUtf8(std::stoul(e["codepoint"].get<std::string>(), nullptr, 16));
    }
    return table;
}

bool listsRuntime(const json &entry) {
    for (const auto &r : entry["runtimes"]) {
        if (r.get<std::string>() == kRuntime) return true;
    }
    return false;
}

// Tokens are joined with one space; a word boundary token " " therefore
// appears as three spaces (two empty parts when split).
std::vector<std::string> splitPhonemes(const std::string &s) {
    std::vector<std::string> tokens;
    if (s.empty()) return tokens;
    int emptyParts = 0;
    size_t start = 0;
    while (true) {
        size_t end = s.find(' ', start);
        std::string part = s.substr(start, end == std::string::npos ? std::string::npos : end - start);
        if (!part.empty()) {
            emptyParts = 0;
            tokens.push_back(part);
        } else if (++emptyParts == 2) {
            emptyParts = 0;
            tokens.emplace_back(" ");
        }
        if (end == std::string::npos) break;
        start = end + 1;
    }
    return tokens;
}

// Points PIPER_PLUS_DICTIONARIES_PATH at the canonical CMU / pinyin files,
// as the Android AAR does, and restores the previous value afterwards.
class ScopedDictionaries {
public:
    ScopedDictionaries() {
        const char *old = std::getenv("PIPER_PLUS_DICTIONARIES_PATH");
        if (old) previous_ = old;
        set(kRoot + "/src/rust/piper-plus-g2p/data");
    }
    ~ScopedDictionaries() { set(previous_); }

private:
    static void set(const std::string &value) {
#ifdef _WIN32
        _putenv_s("PIPER_PLUS_DICTIONARIES_PATH", value.c_str());
#else
        if (value.empty()) {
            unsetenv("PIPER_PLUS_DICTIONARIES_PATH");
        } else {
            setenv("PIPER_PLUS_DICTIONARIES_PATH", value.c_str(), 1);
        }
#endif
    }
    std::string previous_;
};

struct Phonemized {
    bool ok;
    std::string phonemes;
};

Phonemized phonemize(PiperPlusG2pHandle *h, const std::string &text, const std::string &lang) {
    PiperPlusPhonemeResult r{};
    if (piper_plus_g2p_phonemize(h, text.c_str(), lang.c_str(), &r) != PIPER_PLUS_OK) {
        return {false, {}};
    }
    return {true, r.phonemes ? r.phonemes : ""};
}

class G2pGolden : public ::testing::Test {
protected:
    void SetUp() override {
        handle_ = piper_plus_g2p_create(nullptr);
        ASSERT_NE(handle_, nullptr);
    }
    void TearDown() override { piper_plus_g2p_free(handle_); }

    ScopedDictionaries dictionaries_;  // must outlive create()
    PiperPlusG2pHandle *handle_ = nullptr;
};

}  // namespace

TEST_F(G2pGolden, MatchesPythonGoldenExceptListedDivergences) {
    const auto pua = loadPuaTable();
    const json registry = loadJson("tests/fixtures/g2p/known_divergences.json");
    const json golden = loadJson("tests/fixtures/g2p/phoneme_test_cases_golden.json");
    std::set<Key> known;
    for (const auto &e : registry["divergences"]) {
        if (listsRuntime(e)) {
            known.insert({e["language"].get<std::string>(), e["input"].get<std::string>()});
        }
    }

    int verified = 0;
    int knownCount = 0;
    std::vector<std::string> failures;
    for (const auto &c : golden["test_cases"]) {
        const std::string lang = c["language"];
        const std::string input = c["input"];
        if (lang == "ja" || lang == "ko") continue;

        std::vector<std::string> expected;
        for (const auto &t : splitPhonemes(c["expected_phonemes"])) {
            auto it = pua.find(t);
            expected.push_back(it != pua.end() ? it->second : t);
        }
        const auto actual = phonemize(handle_, input, lang);
        const bool matches = actual.ok && expected == splitPhonemes(actual.phonemes);
        ++verified;

        const std::string label = "[" + lang + "] '" + input + "'";
        const bool listed = known.count({lang, input}) > 0;
        if (matches && listed) {
            failures.push_back(label + " now matches; remove it from known_divergences.json");
        } else if (!matches && listed) {
            ++knownCount;
        } else if (!matches) {
            failures.push_back(label + "\n  expected: " + c["expected_phonemes"].get<std::string>() +
                               "\n  actual:   " + (actual.ok ? actual.phonemes : "(phonemize failed)"));
        }
    }

    EXPECT_GT(verified, 0) << "no golden case compared";
    std::string all;
    for (const auto &f : failures) all += f + "\n";
    EXPECT_TRUE(failures.empty()) << failures.size() << " failure(s), " << knownCount
                                  << " known, " << verified << " cases:\n" << all;
}

TEST_F(G2pGolden, EnglishWordsAreNotDropped) {
    const json list = loadJson("tests/fixtures/g2p/english_no_drop_words.json");
    std::set<std::string> knownDrops;
    for (const auto &e : list["known_drops"]) {
        if (listsRuntime(e)) knownDrops.insert(e["word"].get<std::string>());
    }
    static const std::set<std::string> notPhonemes = {
        " ", ".", ",", "!", "?", ";", ":", "'", "\"", "-"};

    std::vector<std::string> failures;
    int checked = 0;
    for (const auto &w : list["words"]) {
        const std::string word = w;
        const auto result = phonemize(handle_, word, "en");
        bool spoken = false;
        for (const auto &t : splitPhonemes(result.phonemes)) {
            if (!notPhonemes.count(t)) spoken = true;
        }
        ++checked;
        const bool listed = knownDrops.count(word) > 0;
        if (spoken && listed) {
            failures.push_back("'" + word + "' is now spoken; remove it from known_drops");
        } else if (!spoken && !listed) {
            failures.push_back("'" + word + "' produced no phoneme: '" + result.phonemes + "'");
        }
    }

    EXPECT_GT(checked, 0) << "english_no_drop_words.json has no words";
    std::string all;
    for (const auto &f : failures) all += f + "\n";
    EXPECT_TRUE(failures.empty()) << all;
}
